const { readFileSync, statSync, cwd } = Deno;

const decoder = new TextDecoder("utf-8");

/**
 * A minimal, require-like loader for CommonJS modules.
 *
 * `makeRequire` returns a function anchored to a given file path. Calling that
 * function with a module specifier resolves and executes the target CommonJS
 * module and returns its `module.exports` value, mirroring the semantics of
 * Node.js' `require`.
