export type RequireFunction = (specifier: string) => unknown;

interface Module {
  id: string;
  exports: unknown;
  loaded: boolean;
}

// Cache of loaded modules keyed by their resolved, absolute filename. The cache
// is what makes circular dependencies work: a module is inserted before its
// body executes, so a cyclic `require` gets the (possibly partial) exports
// object instead of recursing forever.
const moduleCache: Map<string, Module> = new Map();

function isFile(filePath: string): boolean {
  try {
    return statSync(filePath).isFile();
  } catch {
    return false;
  }
}

function isDirectory(dirPath: string): boolean {
  try {
    return statSync(dirPath).isDirectory();
  } catch {
    return false;
  }
}

function readSource(filePath: string): string {
  return decoder.decode(readFileSync(filePath));
